def f3(g):
    h,w=len(g),len(g[0]); b=3
    cnt=Counter(v for r in g for v in r)
    noise={c for c,_ in cnt.most_common(2)}
    out=[[0]*(w//b) for _ in range(h//b)]
    seen=set()
    for i in range(h):
        for j in range(w):
            if (i,j) in seen or g[i][j] in noise: continue
            c=g[i][j]; stack=[(i,j)]; comp=[]; seen.add((i,j))
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and g[ny][nx]==c:
                        seen.add((ny,nx)); stack.append((ny,nx))
            if len(comp)>=2:
                y,x=min(comp)
                out[y//b][x//b]=c
    return out
